import math

def check_cube(n):
    if n == 0:
        return (0, True)

    sign = 1
    if n < 0:
        sign = -1
        n = -n

    # Approximate cube root
    root = round(n**(1/3))

    # Check if it's a perfect cube
    if root * root * root == n:
        return (sign * root, True)
    return (None, False)

candidates = [2, 5, 10, 12]
results = {}

for x in candidates:
    N = (8*x - 41) * (x + 3)**2
    k, is_cube = check_cube(N)
    results[x] = {'N': N, 'is_cube': is_cube, 'k': k}

for x, res in results.items():
    print(f"x={x}: N={res['N']}, is_cube={res['is_cube']}, k={res['k']}")

